import { test, expect } from '@playwright/test';

test.describe('Notification Dismissal', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/notifications');
  });

  test('should dismiss a notification when close button is clicked', async ({ page }) => {
    // Verify notification is visible
    const notification = page.getByRole('alert');
    await expect(notification).toBeVisible();

    // Verify close button is visible
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify notification content is visible
    const notificationText = page.getByText('New message received');
    await expect(notificationText).toBeVisible();

    // Click the close button to dismiss the notification
    await closeButton.click();

    // Verify notification is no longer visible
    await expect(notification).not.toBeVisible();

    // Verify success message appears
    const successMessage = page.getByText('Notification dismissed');
    await expect(successMessage).toBeVisible();
  });

  test('should handle multiple notifications and dismiss them individually', async ({ page }) => {
    // Verify multiple notifications are present
    const notification1 = page.getByRole('alert', { name: /new message/i });
    const notification2 = page.getByRole('alert', { name: /system update/i });
    await expect(notification1).toBeVisible();
    await expect(notification2).toBeVisible();

    // Dismiss the first notification
    const closeButton1 = page.getByRole('button', { name: /close/i });
    await closeButton1.click();

    // Verify first notification is dismissed
    await expect(notification1).not.toBeVisible();

    // Verify second notification is still visible
    await expect(notification2).toBeVisible();

    // Dismiss the second notification
    const closeButton2 = page.getByRole('button', { name: /close/i });
    await closeButton2.click();

    // Verify second notification is dismissed
    await expect(notification2).not.toBeVisible();

    // Verify all notifications are gone
    const allNotifications = page.getByRole('alert');
    await expect(allNotifications).toHaveCount(0);
  });
});
